private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int decodedChars = 0;
    while (bb.hasRemaining()) {
        int b0 = bb.get() & 0xFF;

        // 1-byte ASCII
        if (b0 < 0x80) {
            sb.append((char) b0);
            decodedChars++;
            continue;
        }

        int codepoint = -1;
        int required = 0;

        if ((b0 >> 5) == 0x6) { // 2-byte sequence
            required = 1;
            int b1 = bb.get() & 0xFF;
            codepoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
        } else if ((b0 >> 4) == 0xE) { // 3-byte sequence
            required = 2;
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            codepoint = ((b0 & 0x0F) << 12)
                    | ((b1 & 0x3F) << 6)
                    | (b2 & 0x3F);
        } else if ((b0 >> 3) == 0x1E) { // 4-byte sequence
            required = 3;
            int b1 = bb.get() & 0xFF;
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            codepoint = ((b0 & 0x07) << 18)
                    | ((b1 & 0x3F) << 12)
                    | ((b2 & 0x3F) << 6)
                    | (b3 & 0x3F);
        } else {
            // Invalid leading byte; skip it
            continue;
        }

        // Ensure we had enough bytes for the sequence
        if (required > 0 && bb.remaining() < required) {
            // Not enough bytes; rewind the buffer and exit
            bb.position(bb.position() - required - 1);
            break;
        }

        // Append the decoded code point
        if (codepoint >= 0) {
            sb.append(Character.toChars(codepoint));
            decodedChars++;
        }
    }
    return i + decodedChars;
}

