public String format(LoggingEvent event){
    // Assume a field named 'pattern' holds the conversion pattern string
    String pat = this.pattern; // The conversion pattern (e.g., "%d{yyyy-MM-dd HH:mm:ss} %-5p %c - %m%n")
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < pat.length(); ) {
        char ch = pat.charAt(i);
        if (ch != '%') {
            sb.append(ch);
            i++;
            continue;
        }
        // Handle pattern specifiers
        int j = i + 1;
        if (j >= pat.length()) {
            sb.append('%');
            i++;
            continue;
        }
        char spec = pat.charAt(j);
        switch (spec) {
            case 'd': {
                // Optional date format inside braces: %d{format}
                int braceOpen = pat.indexOf('{', j);
                String dateFormat = "yyyy-MM-dd HH:mm:ss";
                int braceClose = -1;
                if (braceOpen != -1) {
                    braceClose = pat.indexOf('}', braceOpen);
                    if (braceClose != -1) {
                        dateFormat = pat.substring(braceOpen + 1, braceClose);
                        j = braceClose;
                    }
                }
                java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat(dateFormat);
                sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
                i = j + 1;
                break;
            }
            case 'p': // Priority level
                sb.append(event.getLevel().toString());
                i = j + 1;
                break;
            case 'c': // Logger name
                sb.append(event.getLoggerName());
                i = j + 1;
                break;
            case 'm': // Message
                sb.append(event.getMessage());
                i = j + 1;
                break;
            case 'n': // New line
                sb.append(System.lineSeparator());
                i = j + 1;
                break;
            case 't': // Thread name
                sb.append(event.getThreadName());
                i = j + 1;
                break;
            case 'x': // Throwable string (if present)
                Throwable t = event.getThrowable();
                if (t != null) {
                    sb.append(t.toString()).append(System.lineSeparator());
                    for (StackTraceElement ste : t.getStackTrace()) {
                        sb.append("\tat ").append(ste.toString()).append(System.lineSeparator());
                    }
                }
                i = j + 1;
                break;
            default:
                // Unknown specifier – treat literally
                sb.append('%').append(spec);
                i = j + 1;
                break;
        }
    }
    return sb.toString();
}

