public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Determine the size of the serialized message
    int size = schema.getMessageSize(message);
    // Preserve the original size for the return value
    int sizeForReturn = size;

    // Write the size as a Protobuf varint to the output stream
    while ((size & ~0x7F) != 0) {
        out.write((size & 0x7F) | 0x80);
        size >>>= 7;
    }
    out.write(size);

    // Write the actual message contents to the output stream
    schema.writeTo(out, message);

    // Return the original size
    return sizeForReturn;
}

