    // Adjust the method name if your METRICS class provides something else.
    final Object key = data.getKey();

    // Retrieve the current cached value, if any.
    METRICS current = cache.get(key);

    if (current == null) {
        // No existing value – simply put the new one into the cache.
        cache.put(key, data);
