public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength < 0) throw new IndexOutOfBoundsException("byteLength < 0");
    if (byteOffset < 0) throw new IndexOutOfBoundsException("byteOffset < 0");
    // Ensure we have a backing array
    if (data == null) data = new byte[16];
    int needed = position + byteLength;
    if (needed > data.length) {
        int newSize = Math.max(data.length * 2, needed);
        byte[] newData = new byte[newSize];
        System.arraycopy(data, 0, newData, 0, data.length);
        data = newData;
    }
    if (byteArrayValue == null) {
        // Put byteLength null bytes (zeros)
        for (int i = 0; i < byteLength; i++) {
            data[position + i] = 0;
        }
    } else {
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds source array length");
        }
        System.arraycopy(byteArrayValue, byteOffset, data, position, byteLength);
    }
    position += byteLength;
    return this;
}

