        if (cp <= 0x7F) {
            byteCount = 1;
        } else if (cp <= 0x7FF) {
            byteCount = 2;
        } else if (cp <= 0xFFFF) {
            byteCount = 3;
        } else {
            byteCount = 4;
        }
        // Ensure the buffer has enough space for the UTF‑8 bytes.
        lb.ensureRemaining(byteCount);
        switch (byteCount) {
            case 1:
                lb.addByte((byte) cp);
                break;
            case 2:
                lb.addByte((byte) (0xC0 | (cp >> 6)));
                lb.addByte((byte) (0x80 | (cp & 0x3F)));
                break;
            case 3:
                lb.addByte((byte) (0xE0 | (cp >> 12)));
                lb.addByte((byte) (0x80 | ((cp >> 6) & 0x3F)));
                lb.addByte((byte) (0x80 | (cp & 0x3F)));
                break;
            case 4:
                lb.addByte((byte) (0xF0 | (cp >> 18)));
                lb.addByte((byte) (0x80 | ((cp >> 12) & 0x3F)));
                lb.addByte((byte) (0x80 | ((cp >> 6) & 0x3F)));
                lb.addByte((byte) (0x80 | (cp & 0x3F)));
                break;
        }
        i += Character.charCount(cp);
    }
    return lb;
}

public void removeFromTreeEdgeList() {
    // Remove from source node's tree‑edge list
    if (sourceTreeEdgePrev != null) {
        sourceTreeEdgePrev.sourceTreeEdgeNext = sourceTreeEdgeNext;
    } else {
        source.firstTreeEdge = sourceTreeEdgeNext;
    }
    if (sourceTreeEdgeNext != null) {
        sourceTreeEdgeNext.sourceTreeEdgePrev = sourceTreeEdgePrev;
    }

    // Remove from target node's tree‑edge list
    if (targetTreeEdgePrev != null) {
        targetTreeEdgePrev.targetTreeEdgeNext = targetTreeEdgeNext;
    } else {
        target.firstTreeEdge = targetTreeEdgeNext;
    }
    if (targetTreeEdgeNext != null) {
        targetTreeEdgeNext.targetTreeEdgePrev = targetTreeEdgePrev;
    }

    // Disconnect this edge's references
    sourceTreeEdgePrev = sourceTreeEdgeNext = null;
    targetTreeEdgePrev = targetTreeEdgeNext = null;
}

public static String findAndSubst(String key, Properties props){
    String value = props == null ? null : props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Regular expression to match ${variableName}
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    while (matcher.find()) {
        String varName = matcher.group(1);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = "";
        }
        matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
    }
    matcher.appendTail(sb);
    String result = sb.toString();

    // Repeat substitutions for nested placeholders
    while (pattern.matcher(result).find()) {
        matcher = pattern.matcher(result);
        sb = new java.lang.StringBuilder();
        while (matcher.find()) {
            String varName = matcher.group(1);
            String replacement = props.getProperty(varName);
            if (replacement == null) {
                replacement = "";
            }
            matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(sb);
        result = sb.toString();
    }

    return result;
}

