private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, treat as a match
    if (str == null && suffix == null) {
        return true;
    }
    // If only one is null, not a match
    if (str == null || suffix == null) {
        return false;
    }

    int strLen = str.length();
    int sufLen = suffix.length();

    // Suffix longer than string cannot match
    if (sufLen > strLen) {
        return false;
    }

    // If suffix is empty, every string ends with an empty suffix
    if (sufLen == 0) {
        return true;
    }

    if (ignoreCase) {
        // Use regionMatches with ignoreCase
        return str.regionMatches(true, strLen - sufLen, suffix, 0, sufLen);
    } else {
        // Use standard endsWith
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Ignore the leading slash for absolute path components
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    // Split by '/' while preserving trailing empty segments
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, keep the original segment
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

