private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int idx = 0;
    boolean isMethod = descriptor.charAt(0) == '(';
    if (isMethod) {
        idx = 1; // skip '('
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            idx = popType(descriptor, idx);
        }
        // ignore return type after ')'
    } else {
        popType(descriptor, idx);
    }
}

private int popType(final String desc, int idx) {
    char c = desc.charAt(idx);
    switch (c) {
        case 'B': case 'C': case 'D': case 'F': case 'I':
        case 'J': case 'S': case 'Z':
            outputStack.pop(); // pop one entry from the frame stack
            return idx + 1;
        case 'V':
            // void: nothing to pop
            return idx + 1;
        case '[':
            // consume all '[' characters
            while (idx < desc.length() && desc.charAt(idx) == '[') {
                idx++;
            }
            // recursively process the element type
            return popType(desc, idx);
        case 'L':
            int end = desc.indexOf(';', idx);
            if (end == -1) {
                throw new IllegalArgumentException("Invalid descriptor: " + desc);
            }
            outputStack.pop(); // pop the object type
            return end + 1;
        default:
            throw new IllegalArgumentException("Unknown descriptor char: " + c);
    }
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException();
    }
    if (off < 0 || len < 0 || (off + len) > b.length || (off + len) < 0) {
        throw new IndexOutOfBoundsException();
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newCap = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

