    if (targetVertex == null) {
        throw new NullPointerException("Target vertex cannot be null");
    }
    // Ensure edge is not null
    if (e == null) {
        throw new NullPointerException("Edge cannot be null");
    }

    // If the index map hasn't been created yet, initialize it.
    // This assumes there is a field `protected Map<V, Map<V, List<E>>> index`
    // that holds the graph index.
    Map<V, Map<V, List<E>>> index = getIndex(); // Adjust this to the actual field name if different.

