private void enlarge(final int size) {
    // Determine the amount of data currently stored
    int used = this.size;          // number of bytes already in the vector
    // Calculate the new capacity needed to fit the additional data
    int needed = used + size;

    // If the current backing array is already large enough, do nothing
    if (needed <= array.length) {
        return;
    }

    // Compute a new capacity - start with double the previous size for amortized O(1)
    int newCapacity = array.length * 2;
    if (newCapacity < needed) {
        newCapacity = needed;
    }

    // Allocate the new array and copy the existing contents over
    byte[] newArray = new byte[newCapacity];
    System.arraycopy(array, 0, newArray, 0, used);

    // Replace the old backing array with the new one
    array = newArray;
}

