@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Expecting conversion only to Character or char
    if (!Character.class.isAssignableFrom(type) && !type.equals(char.class)) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // String or CharSequence of length 1
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert CharSequence to Character, length != 1: " + value);
        }
    }

    // Numeric types: take numeric value and cast to char
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }

    // Fallback: use toString() representation
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    throw new IllegalArgumentException("Cannot convert value to Character: " + value);
}

