public final byte[] toByteArray() {
    byte[] data = new byte[this.count];
    if (this.count == 0) {
        return data;
    }
    int pos = 0;
    for (int i = 0; i < this.chunks.length; i++) {
        byte[] chunk = this.chunks[i];
        int len = chunk.length;
        if (pos + len > this.count) {
            len = this.count - pos;
        }
        System.arraycopy(chunk, 0, data, pos, len);
        pos += len;
    }
    return data;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case '0':
                    sb.append('\0');
                    i++;
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new IllegalArgumentException("Invalid Unicode escape at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        sb.append((char) value);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape at position " + i, e);
                    }
                    i += 5;
                    break;
                default:
                    if ('0' <= next && next <= '7') {
                        int j = i + 1;
                        int end = j;
                        while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                            end++;
                        }
                        String oct = str.substring(j, end);
                        try {
                            int val = Integer.parseInt(oct, 8);
                            sb.append((char) val);
                        } catch (NumberFormatException e) {
                            sb.append('\\').append(next);
                        }
                        i = end - 1;
                    } else {
                        sb.append('\\').append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

