private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        // If the input array is null, create a new array of size 1 using the supplied component type.
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("newArrayComponentType must not be null when array is null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    // Verify that the provided object is indeed an array
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }

    int oldLength = java.lang.reflect.Array.getLength(array);
    int newLength = oldLength + 1;
    Class<?> componentType = arrayClass.getComponentType();
    Object newArray = java.lang.reflect.Array.newInstance(componentType, newLength);
    // Copy existing elements; the last element is automatically set to the default value.
    java.lang.System.arraycopy(array, 0, newArray, 0, oldLength);
    return newArray;
}

private int computeBinaryLog(int n){
    if (n <= 0) {
        // Logarithm is undefined for non‑positive values; return 0 by convention
        return 0;
    }
    int count = 0;
    while (n > 0) {
        count++;
        n >>= 1;
    }
    return count;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return Collections.emptySet();
    }
    // Create a result set with an initial capacity equal to the size of the smaller set
    Set<V> result = new HashSet<>(Math.min(set1.size(), set2.size()));
    // Iterate over the smaller set to reduce contain checks
    if (set1.size() <= set2.size()) {
        for (V element : set1) {
            if (set2.contains(element)) {
                result.add(element);
            }
        }
    } else {
        for (V element : set2) {
            if (set1.contains(element)) {
                result.add(element);
            }
        }
    }
    return result;
}

