private CategoryNode prune(CategoryNode node, int[] removed) {
    if (node == null) {
        return null;
    }
    if (!node.isActive()) {
        removed[0] += countNodes(node);
        return null;
    }
    List<CategoryNode> children = node.getChildren();
    for (int i = children.size() - 1; i >= 0; i--) {
        CategoryNode child = children.get(i);
        CategoryNode pruned = prune(child, removed);
        if (pruned == null) {
            children.remove(i);
        } else {
            children.set(i, pruned);
        }
    }
    return node;
}

private int countNodes(CategoryNode node) {
    int count = 1;
    for (CategoryNode child : node.getChildren()) {
        count += countNodes(child);
    }
    return count;
}

