final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // The offset of each constant-pool entry is stored in the array `constantPoolEntryOffset`;
    // it is assumed that this field has been initialized by the class constructor.
    int offset = constantPoolEntryOffset[constantPoolEntryIndex];
    // The first byte of the entry is the tag.
    if ((classFileBuffer[offset++] & 0xFF) != 1) {
        // Not a CONSTANT_Utf8 entry – return null or throw an exception as appropriate.
        return null;
    }
    // The next two bytes give the length of the UTF-8 byte sequence.
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    // Safety check: make sure we do not read past the buffer.
    if (length < 0 || offset + length > classFileBuffer.length) {
        return null;
    }
    // Convert the bytes to a Java String using UTF‑8 encoding.
    java.nio.charset.Charset utf8 = java.nio.charset.Charset.forName("UTF-8");
    String result = new String(classFileBuffer, offset, length, utf8);
    // Copy the characters into the supplied buffer, if it is large enough.
    if (charBuffer == null || charBuffer.length < result.length()) {
        return null; // buffer too small; caller should handle this situation.
    }
    result.getChars(0, result.length(), charBuffer, 0);
    return result;
}

