private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize a circulator at the starting node, respecting the traversal direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Continue traversing until we reach the stop node or find a node that satisfies the predicate.
    while (!circ.node().equals(stop) && !predicate.test(circ.node())) {
        // Move to the next or previous node based on the direction.
        circ = dir > 0 ? circ.next() : circ.prev();
    }

    // Return the circulator positioned at the satisfying node or at the stop node.
    return circ;
}

