public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength cannot be negative");
    }
    if (byteLength == 0) {
        return this;
    }

    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length || byteLength > byteArrayValue.length - byteOffset) {
            throw new ArrayIndexOutOfBoundsException("Invalid byteOffset/byteLength for the provided array");
        }
    }

    int newSize = this.size + byteLength;
    if (newSize > this.data.length) {
        int newCapacity = Math.max(this.data.length * 2, newSize);
        this.data = java.util.Arrays.copyOf(this.data, newCapacity);
    }

    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.size, byteLength);
    } else {
        java.util.Arrays.fill(this.data, this.size, this.size + byteLength, (byte) 0);
    }

    this.size = newSize;
    return this;
}

