private void check(String modelName) throws IllegalStateException {
    try {
        Class<?> clazz = Class.forName(modelName);
        java.lang.reflect.Field f = clazz.getDeclaredField("SHARDING_KEYS");
        @SuppressWarnings("unchecked")
        java.util.List<Integer> indices = (java.util.List<Integer>) f.get(null);
        if (indices == null || indices.isEmpty()) {
            return;
        }
        java.util.Collections.sort(indices);
        int expected = 0;
        for (int idx : indices) {
            if (idx != expected) {
                throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
            }
            expected++;
        }
    } catch (ClassNotFoundException | NoSuchFieldException | IllegalAccessException e) {
        throw new IllegalStateException("Failed to check sharding key indices for model: " + modelName, e);
    }
}

