@Override public Action inspect(AtmosphereResource r){
    // Suspend the resource for transports that support blocking I/O
    // (e.g. HTTP, long-polling or SSE).  For WebSocket we do nothing
    // as it is always a streaming transport.
    switch(r.getTransport()){
        case HTTP:
        case LONG_POLLING:
        case EVENT_SOURCE:
            if (!r.isSuspended()){
                r.suspend();
            }
            break;
        case WEBSOCKET:
            // WebSocket is always open, no explicit suspend needed
            break;
        default:
            // Fallback: suspend if not already suspended
            if (!r.isSuspended()){
                r.suspend();
            }
    }
    return Action.CONTINUE;
}

public double vertexWeight(Set<V> v){
