    for (V vertex : v) {
        try {
            java.lang.reflect.Method m = vertex.getClass().getMethod("getWeight");
            Object result = m.invoke(vertex);
            if (result instanceof Number) {
                sum += ((Number) result).doubleValue();
            }
        } catch (Exception ignored) {
            // Ignore elements that do not provide a getWeight() method or if invocation fails.
        }
    }
    return sum;
}

