int addConstantNameAndType(final String name, final String descriptor){
    // Ensure that the name and descriptor strings are already in the constant pool
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);

    /* Search the constant pool for an existing CONSTANT_NameAndType_info with the same
     * name and descriptor indices. If found, simply return its index (constant pool
     * indices are 1‑based in the class file format). */
    for (int i = 0; i < constantPool.size(); i++) {
        CPInfo cpInfo = constantPool.get(i);
        if (cpInfo instanceof NameAndTypeInfo) {
            NameAndTypeInfo ntInfo = (NameAndTypeInfo) cpInfo;
            if (ntInfo.getNameIndex() == nameIndex && ntInfo.getDescriptorIndex() == descriptorIndex) {
                return i + 1; // 1‑based index
            }
        }
    }

    // If not found, create a new CONSTANT_NameAndType_info and append it to the pool
    NameAndTypeInfo newNtInfo = new NameAndTypeInfo(nameIndex, descriptorIndex);
    constantPool.add(newNtInfo);
    return constantPool.size(); // index of the newly added entry (1‑based)
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Strip surrounding quotes if present (DOT identifiers may be quoted)
    if (input.length() >= 2 && input.charAt(0) == '"' && input.charAt(input.length() - 1) == '"') {
        // Handle escaped quotes inside the string; ensure that the ending quote is not escaped
        // by looking at the number of consecutive backslashes immediately before it.
        boolean endingQuoteEscaped = false;
        int backslashCount = 0;
        for (int i = input.length() - 2; i >= 0; i--) {
            if (input.charAt(i) == '\\') {
                backslashCount++;
            } else {
                break;
            }
        }
        if (backslashCount % 2 != 0) {
            endingQuoteEscaped = true;
        }
        // Only strip if ending quote is not escaped
        if (!endingQuoteEscaped) {
            input = input.substring(1, input.length() - 1);
        }
    }

    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            // Skip escape character and append the escaped character literally
            sb.append(input.charAt(i + 1));
            i++; // Skip the escaped character
        } else {
