private String parseToken(final char[] terminators){
    if (input == null) {
        return null;
    }
    int start = pos;
    while (pos < input.length()) {
        char c = input.charAt(pos);
        boolean isTerminator = false;
        for (char t : terminators) {
            if (c == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        pos++;
    }
    if (pos == start) {
        return null; // no token found
    }
    return input.substring(start, pos);
}

