private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>(bounds.size());
    long totalSum = 0L;

    // Compute total sum of all elements
    for (Integer val : bounds) {
        totalSum += val;
    }

    // Compute suffix sums from the end
    long currentSuffix = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSuffix += bounds.get(i);
        suffixSumList.add(0, (int) currentSuffix);
    }

    return new Pair<>(suffixSumList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range specified");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Nothing to move if the source is empty or if it's the same list
    if (list == this || list.size == 0) {
        return;
    }

    // If the target list is empty, simply adopt the nodes
    if (this.size == 0) {
        this.first = list.first;
        this.last  = list.last;
    } else {
        // Connect the last node of the target list to the first node of the source list
        this.last.next = list.first;
        list.first.prev = this.last;
        this.last = list.last;
    }

    // Update size and clear the source list
    this.size += list.size;
    list.first = null;
    list.last  = null;
    list.size  = 0;
}

