private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (K key : keys) {
        if (!(key instanceof Number)) {
            bounds.add(null);
            continue;
        }
        int target = ((Number) key).intValue();
        int best = Integer.MIN_VALUE;
        for (K candidate : keys) {
            if (candidate instanceof Number) {
                int val = ((Number) candidate).intValue();
                if (val <= target && val > best) {
                    best = val;
                }
            }
        }
        bounds.add(best);
    }
    return bounds;
}

private void pop(final String descriptor) {
    // The stack that holds the output frame values.
    // It is assumed to have a pop() method that removes the top value.
    // (e.g., java.util.Stack<AbstractType> stack)
    int i = 0;
    int len = descriptor.length();

    if (len == 0) {
        return; // nothing to pop
    }

    // If the descriptor is a method descriptor, we only pop its argument types.
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < len) {
            char ch = descriptor.charAt(i);
            if (ch == ')') {
                // end of argument list, ignore return type
                break;
            }
            // skip one argument descriptor
            if (ch == '[') {
                // Skip all '[' array-indicators
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                // Now at component type
                if (i < len && descriptor.charAt(i) == 'L') {
                    // Object type: skip until ';'
                    i = descriptor.indexOf(';', i) + 1;
                } else {
                    // Primitive type: skip single char
                    i++;
                }
            } else if (ch == 'L') {
                // Object type: skip until ';'
                i = descriptor.indexOf(';', i) + 1;
            } else {
                // Primitive type: skip single char
                i++;
            }
            // Pop one value from the stack for this argument type
            stack.pop();
        }
        // No further action: method return type is ignored
        return;
    }

    // Descriptor is a single type (not a method)
    // Skip the type descriptor
    ch = descriptor.charAt(i);
    if (ch == '[') {
        while (i < len && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i < len && descriptor.charAt(i) == 'L') {
            i = descriptor.indexOf(';', i) + 1;
        } else {
            i++;
        }
    } else if (ch == 'L') {
        i = descriptor.indexOf(';', i) + 1;
    } else {
        i++;
    }
    // Pop the value represented by this type
    stack.pop();
}

