public static String applyRelativePath(String path, String relativePath) {
    if (path == null || path.isEmpty()) {
        return relativePath == null ? "" : relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    boolean isAbsolute = path.startsWith("/");
    // Build base parts from the given path (excluding the last component if it's a file)
    String[] pathTokens = path.split("/");
    int limit = pathTokens.length;
    if (!path.endsWith("/") && limit > 0) {
        limit--; // drop the last token (assumed to be a file)
    }
    java.util.List<String> parts = new java.util.ArrayList<>();
    for (int i = 0; i < limit; i++) {
        String token = pathTokens[i];
        if (token.isEmpty() || token.equals(".")) {
            continue;
        }
        parts.add(token);
    }
    // Process the relative path components
    for (String seg : relativePath.split("/")) {
        if (seg.isEmpty() || seg.equals(".")) {
            // skip
        } else if (seg.equals("..")) {
            if (!parts.isEmpty()) {
                parts.remove(parts.size() - 1);
            } else if (!isAbsolute) {
                // For relative paths that go above the initial location,
                // keep the ".." component to reflect that navigation.
                parts.add("..");
            }
        } else {
            parts.add(seg);
        }
    }
    // Assemble the final path
    StringBuilder sb = new StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    for (int i = 0; i < parts.size(); i++) {
        sb.append(parts.get(i));
        if (i < parts.size() - 1) {
            sb.append("/");
        }
    }
    String result = sb.toString();
    if (result.isEmpty() && isAbsolute) {
        result = "/";
    }
    return result;
}

