private void checkIfPackedField() throws IOException {
    // Determine the field number and wire type from the current tag.
    int fieldNumber = (tag >>> 3);
    int wireType = tag & 0x7;

    // Look up the descriptor for this field.
    FieldDescriptor field = descriptor.findFieldByNumber(fieldNumber);
    if (field == null) {
        // No descriptor - nothing to do.
        return;
    }

    // Detect a packed repeated field, which is represented as a length‑delimited
    // wire type (wire type 2).  If the field is repeated and marked as packed
    // we prepare to read a packed block by setting up a sub‑limit.
    if (wireType == WireFormatLite.WIRETYPE_LENGTH_DELIMITED
            && field.isRepeated()
            && field.isPacked()) {
        // Read the packed block length.
        int packedLength = input.readRawVarint32();

        // Push a new limit for the packed block and remember the previous limit.
        oldLimit = input.pushLimit(packedLength);

        // Mark that subsequent reads should treat this as a packed field.
        currentPackedField = field;
        isReadingPacked = true;
    }
}

public int readTag() throws IOException {
    if (isAtEnd()) {
        return 0;
    }
    int tag = readRawVarint32();
    if (tag == 0) {
        throw InvalidProtocolBufferException.invalidTag();
    }
    return tag;
}

final ByteVector put11(final int byteValue1, final int byteValue2){
    write((byte) byteValue1);
    write((byte) byteValue2);
    return this;
}

private String buildContentRange(){
    // Build a valid Content-Range header value.
    // It is assumed that the class has the following fields:
    //   long contentLength   - the total size of the resource
    //   long rangeStart      - start byte of the requested range
    //   long rangeEnd        - end byte of the requested range
    if (contentLength <= 0 || rangeStart < 0 || rangeEnd < 0) {
        return null;
    }
    return String.format("bytes %d-%d/%d", rangeStart, rangeEnd, contentLength);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        List<String> block = new ArrayList<>();
        String line;
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss.SSS");
        ZoneId zone = ZoneOffset.UTC;
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) {
                if (!block.isEmpty()) {
                    String timestampLine = block.get(0).trim();
                    long timestamp;
                    try {
                        LocalDateTime ldt = LocalDateTime.parse(timestampLine, formatter);
                        timestamp = ldt.atZone(zone).toInstant().toEpochMilli();
                    } catch (Exception e) {
                        // if timestamp cannot be parsed, skip this block
                        block.clear();
                        continue;
                    }
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                            try {
                                ThreadSnapshot ts = ThreadSnapshot.fromLines(block);
                                result.add(ts);
                            } catch (Exception e) {
                                // if parsing the snapshot fails, ignore and continue
                            }
                            break;
                        }
                    }
                    block.clear();
                }
            } else {
                block.add(line);
            }
        }
        // handle last block if file doesn't end with blank line
        if (!block.isEmpty()) {
            String timestampLine = block.get(0).trim();
            long timestamp;
            try {
                LocalDateTime ldt = LocalDateTime.parse(timestampLine, formatter);
                timestamp = ldt.atZone(zone).toInstant().toEpochMilli();
            } catch (Exception e) {
                block.clear();
                return result;
            }
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                    try {
                        ThreadSnapshot ts = ThreadSnapshot.fromLines(block);
                        result.add(ts);
                    } catch (Exception e) {
                        // ignore parse failure
                    }
                    break;
                }
            }
            block.clear();
        }
    }
    return result;
}
